-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.release_text(html text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select btrim(regexp_replace(
    replace(replace(replace(replace(replace(replace(replace(
      regexp_replace(
        regexp_replace(coalesce(html, ''),
                       '<(?:img|video|audio|source|embed)\M[^>]*\m(?:data-media|src)\s*=\s*'
                       || '(?:"([^"]*)"|''([^'']*)''|([^\s"''>]+))[^>]*>', ' [img \1\2\3] ', 'gi'),
        '</?[a-z][^>]*>|<![^>]*>', ' ', 'gi'),
      '&nbsp;', ' '), '&lt;', '<'), '&gt;', '>'), '&quot;', '"'), '&#39;', ''''), '&amp;', '&'),
      chr(160), ' '),
    '\s+', ' ', 'g'));
$function$;
